// The /sample page's own words, in both languages.
//
// Kept beside the page (like landingStrings.ts beside the landing) and NOT
// in the i18n locale files: the page is public, loads before any app
// surface does, and its copy is reviewed as one piece.
//
// WHAT IS NOT HERE. No measured figure, no count, no date and no engine
// sentence. Every number the page prints is read from
// frontend/data/publicSample.json
// (generated by scripts/build_public_sample.py from the served documents), and
// the engine's sentences are quoted from that file verbatim. A sentence
// below that needs a figure takes it as a `{placeholder}`.
//
// Romanian: informal tu-form, comma-below diacritics.

import type { FileKey, SampleLang } from "@/lib/publicSample";

export interface SampleStrings {
  metaTitle: string;
  metaDescription: string;
  home: string;
  otherLanguage: string;
  eyebrow: string;
  title: string;
  /** {company} */
  lede: string;
  fictionalTitle: string;
  /** {fiscalCode} {tradeRegister} */
  fictionalBody: string;
  facts: { activity: string; years: string; accounts: string; asOf: string };
  /** {current} {prior} */
  yearsValue: string;
  /** {n} {period} */
  accountsValue: string;

  downloadsTitle: string;
  downloadsLede: string;
  download: string;
  open: string;
  /** {size} */
  sizeKb: string;
  files: Record<FileKey, { title: string; body: string }>;

  figuresTitle: string;
  figuresLede: string;
  figure: string;
  figures: Record<string, string>;
  ratiosTitle: string;
  ratiosLede: string;
  ratio: string;

  verdictsTitle: string;
  verdictsLede: string;
  verdict: {
    balanceTitle: string;
    /** {status} {assets} {liabilities} {difference} */
    balanceBody: string;
    /** {n} */
    balanceSource: string;
    anchorTitle: string;
    /** {value} */
    anchorBody: string;
    /** {reconstructed} {variation} */
    anchorBridge: string;
    variationTitle: string;
    /** {value} */
    variationBody: string;
    ebitdaTitle: string;
    /** {value} */
    ebitdaBody: string;
    /** {difference} */
    ebitdaVariants: string;
    ebitdaVariantNames: Record<string, string>;
    creditTitle: string;
    /** {letter} {composite} {z} {zone} */
    creditBody: string;
    zones: Record<string, string>;
    inventoryTitle: string;
    /** {days} {basis} */
    inventoryBody: string;
    inventorySeasonal: string;
    cashFlowTitle: string;
    cashFlowApproximated: string;
    cashFlowExact: string;
    findingsTitle: string;
    /** {n} */
    findingsBody: string;
    levels: Record<string, string>;
    findingsEnglish: string;
  };

  labelsTitle: string;
  /** {n} */
  labelsLede: string;
  engineWords: string;
  engineWordsEnglishOnly: string;
  kinds: Record<string, string>;
  areas: Record<string, string>;
  labelTitles: Record<string, string>;
  /** The title of an insight the engine checked and did not raise, for an
   *  id this table does not name. {id} */
  labelNotFiredFallback: string;
  /** {ratio} */
  labelRatioRefused: string;

  mappingTitle: string;
  /** {n} */
  mappingLede: string;
  mappingColumns: { account: string; name: string; line: string; amount: string };
  statements: Record<string, string>;
  buckets: Record<string, string>;
  sections: Record<string, string>;
  mappingStatus: Record<string, string>;
  /** {value} */
  mappingNoteDerived: string;
  /** {n} */
  showAll: string;
  showFewer: string;

  howTitle: string;
  howSteps: string[];
  howGate: string;
  engineTitle: string;
  engine: Record<string, string>;
  notIncludedTitle: string;
  notIncluded: string[];

  ctaTitle: string;
  ctaBody: string;
  ctaPrimary: string;
  ctaSecondary: string;
}

