export function sampleStringsFor(language: string | null | undefined): SampleStrings {
  return sampleLangOf(language) === "ro" ? RO : EN;
}

export function sampleLangOf(language: string | null | undefined): SampleLang {
  return (language ?? "").toLowerCase().startsWith("ro") ? "ro" : "en";
}

/** `{name}` placeholders filled from `values`; an unfilled placeholder is
 *  a bug in the caller and stays visible. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
    Object.prototype.hasOwnProperty.call(values, name) ? values[name] : whole,
  );
}

export const SAMPLE_STRINGS: Record<SampleLang, SampleStrings> = { en: EN, ro: RO };
